import { DomainError } from "../domain/errors";
import { Project } from "../domain/project";
import { ProjectRepository, TaskFilter, TaskRepository, UserRepository } from "../domain/repositories";
import { Task } from "../domain/task";
import { TaskStatus } from "../domain/task-status";
import { User } from "../domain/user";
import { NotFoundError } from "./errors";

export interface CreateProjectDto { id: string; name: string; }
export interface CreateUserDto { id: string; name: string; }
export interface CreateTaskDto {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate?: string;
  assigneeId?: string;
  status?: TaskStatus;
}

/** Coordinates task workflows while leaving storage details to repository interfaces. */
export class TaskService {
  public constructor(
    private readonly projects: ProjectRepository,
    private readonly users: UserRepository,
    private readonly tasks: TaskRepository,
  ) {}

  public createProject(dto: CreateProjectDto): Project {
    const project = new Project(dto.id, dto.name);
    this.projects.save(project);
    return project;
  }

  public createUser(dto: CreateUserDto): User {
    const user = new User(dto.id, dto.name);
    this.users.save(user);
    return user;
  }

  public createTask(dto: CreateTaskDto): Task {
    this.requireProject(dto.projectId);
    if (dto.assigneeId !== undefined && !this.users.findById(dto.assigneeId)) {
      throw new DomainError("Assignee does not exist");
    }
    const task = new Task(dto.id, dto.projectId, dto.title, dto.description, dto.dueDate, dto.assigneeId, dto.status);
    this.tasks.save(task);
    return task;
  }

  public listProjectTasks(projectId: string, filter?: TaskFilter): Task[] {
    this.requireProject(projectId);
    return this.tasks.findByProject(projectId, filter);
  }

  public markTaskDone(taskId: string): Task {
    const task = this.tasks.findById(taskId);
    if (!task) throw new NotFoundError("Task not found");
    const completed = task.markDone();
    this.tasks.save(completed);
    return completed;
  }

  private requireProject(id: string): void {
    if (!this.projects.findById(id)) throw new NotFoundError("Project not found");
  }
}

=====SOURCE-END=====

